<?php
declare(strict_types=1); namespace App\Application\FinancialDistribution;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter}; use App\Models\{CommissionAccrual,CommissionRuleVersion,Policy,User}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class CommissionService {
 public function __construct(private AuditWriter $audit,private OutboxWriter $outbox,private DistributionEventWriter $events){}
 public function createRule(array $d,User $actor):CommissionRuleVersion{return DB::transaction(function()use($d,$actor){if(($d['basis_points']??10001)>10000||($d['holdback_basis_points']??10001)>10000)throw ValidationException::withMessages(['basis_points'=>__('wave6.invalid_basis_points')]); if(isset($d['conditions'])&&is_array($d['conditions']))$d['conditions']=CommissionReference::normaliseConditions($d['conditions']);$tiers=$d['tiers']??[];$splits=$d['splits']??[];unset($d['tiers'],$d['splits']);if(isset($d['transaction_type']))$d['transaction_type']=strtoupper($d['transaction_type']);if(isset($d['line_code']))$d['line_code']=strtoupper($d['line_code']);DB::statement("SELECT pg_advisory_xact_lock(hashtext(?))",[implode(':',[$d['tenant_id'],$d['carrier_id'],$d['product_id']??'*',$d['partner_id']??'*'])]);$version=(int)CommissionRuleVersion::where('carrier_id',$d['carrier_id'])->where('product_id',$d['product_id']??null)->where('partner_id',$d['partner_id']??null)->max('version')+1;$canonical=json_encode([...$d,'tiers'=>$tiers,'splits'=>$splits],JSON_THROW_ON_ERROR);$r=CommissionRuleVersion::create([...$d,'version'=>$version,'status'=>'DRAFT','rule_hash'=>hash('sha256',$canonical),'created_by'=>$actor->id]);app(\App\Application\Commissions\Rules\CommissionRuleComponents::class)->store($r,$tiers,$splits);$this->audit->record('commission.rule.created','commission_rule_version',$r->id,['version'=>$version]);return$r;});}
 public function approveRule(CommissionRuleVersion $r,User $actor):CommissionRuleVersion{return DB::transaction(function()use($r,$actor){$r=CommissionRuleVersion::lockForUpdate()->findOrFail($r->id);if($r->status!=='DRAFT'||$r->created_by===$actor->id)throw ValidationException::withMessages(['rule'=>__('wave6.maker_checker')]);app(\App\Application\Commissions\Rules\CommissionRuleComponents::class)->assertApprovable($r);$overlap=CommissionRuleVersion::where('id','<>',$r->id)->where('status','APPROVED')->where('carrier_id',$r->carrier_id)->where('product_id',$r->product_id)->where('partner_id',$r->partner_id)->where('agreement_id',$r->agreement_id)->where('line_code',$r->line_code)->where('transaction_type',$r->transaction_type)->whereDate('effective_from','<=',$r->effective_until??'9999-12-31')->where(fn($q)=>$q->whereNull('effective_until')->orWhereDate('effective_until','>=',$r->effective_from))->exists();if($overlap)throw ValidationException::withMessages(['effective_from'=>__('wave6.rule_overlap')]);$r->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$this->events->write($r->tenant_id,'COMMISSION_RULE',$r->id,'DRAFT','APPROVED','APPROVED',$actor);$this->outbox->record('commission.rule.approved','commission_rule_version',$r->id,['rule_id'=>$r->id]);return$r->refresh();});}
 public function accrue(Policy $p,CommissionRuleVersion $r,string $partnerId,string $key):CommissionAccrual{return DB::transaction(function()use($p,$r,$partnerId,$key){if($p->tenant_id!==$r->tenant_id||$r->status!=='APPROVED')throw ValidationException::withMessages(['rule'=>__('wave6.rule_not_applicable')]);if($existing=CommissionAccrual::where('tenant_id',$p->tenant_id)->where('idempotency_key',$key)->first())return$existing;$gross=$p->premium_minor;$calc=app(\App\Application\Commissions\Rules\CommissionRuleResolver::class)->compute($r,(int)$gross,$p->issued_at??now(),$partnerId);$earned=$calc->amountMinor;$held=intdiv($earned*$r->holdback_basis_points,10000);$a=CommissionAccrual::create(['tenant_id'=>$p->tenant_id,'policy_id'=>$p->id,'partner_id'=>$partnerId,'rule_version'=>(string)$r->version,'rule_version_id'=>$r->id,'amount_minor'=>$earned,'vested_minor'=>0,'paid_minor'=>0,'clawed_back_minor'=>0,'currency'=>$p->currency,'status'=>'PENDING','vests_at'=>now()->addDays($r->vesting_days),'available_at'=>now()->addDays($r->vesting_days),'source_type'=>'POLICY','source_id'=>$p->id,'idempotency_key'=>$key]);DB::table('commission_movements')->insert(['id'=>(string)\Illuminate\Support\Str::uuid(),'commission_accrual_id'=>$a->id,'type'=>'ACCRUAL','amount_minor'=>$earned-$held,'currency'=>$p->currency,'reason_code'=>'POLICY_ISSUED','occurred_at'=>now(),'metadata'=>json_encode(['holdback_minor'=>$held,'basis_points'=>$calc->basisPoints,'splits'=>$calc->splits],JSON_THROW_ON_ERROR)]);$this->outbox->record('commission.accrued','commission_accrual',$a->id,['accrual_id'=>$a->id]);return$a;});}
 public function vest(CommissionAccrual $a):CommissionAccrual{return DB::transaction(function()use($a){$a=CommissionAccrual::lockForUpdate()->findOrFail($a->id);if($a->status!=='PENDING'||$a->vests_at->isFuture())throw ValidationException::withMessages(['accrual'=>__('wave6.not_vestable')]);$amount=$a->amount_minor-$a->clawed_back_minor;$a->update(['status'=>'VESTED','vested_minor'=>$amount]);$this->events->write($a->tenant_id,'COMMISSION_ACCRUAL',$a->id,'PENDING','VESTED','VESTING_ELAPSED',null);return$a->refresh();});}
 public function clawback(CommissionAccrual$a,int$amount,string$reason,User$actor):CommissionAccrual{return DB::transaction(function()use($a,$amount,$reason,$actor){$a=CommissionAccrual::lockForUpdate()->findOrFail($a->id);$available=$a->amount_minor-$a->clawed_back_minor-$a->paid_minor;if($amount<=0||$amount>$available)throw ValidationException::withMessages(['amount_minor'=>__('wave6.clawback_exceeds_available')]);$a->increment('clawed_back_minor',$amount);DB::table('commission_movements')->insert(['id'=>(string)\Illuminate\Support\Str::uuid(),'commission_accrual_id'=>$a->id,'type'=>'CLAWBACK','amount_minor'=>-$amount,'currency'=>$a->currency,'reason_code'=>$reason,'actor_id'=>$actor->id,'occurred_at'=>now(),'metadata'=>'{}']);$this->events->write($a->tenant_id,'COMMISSION_ACCRUAL',$a->id,$a->status,$a->status,$reason,$actor,['amount_minor'=>$amount]);$this->outbox->record('commission.clawed_back','commission_accrual',$a->id,['amount_minor'=>$amount]);return$a->refresh();});}
}
